 btn.onclick=function(){menu.hidden=!menu.hidden;btn.setAttribute("aria-expanded",menu.hidden?"false":"true");if(!menu.hidden){var c=menu.querySelector('[aria-checked="true"]')||menu.firstChild;c.focus()}};
 document.addEventListener("click",function(e){if(!box.contains(e.target))close()});
